export const meta = {
  name: 'status-report-factcheck',
  description: 'Fact-check the plan status report against the repository and find omitted open items',
  phases: [{ title: 'Verify', detail: 'one skeptic per report section' }, { title: 'Complete', detail: 'critics look for remaining work the draft omits' }],
}
const DRAFT = '/tmp/claude-0/-home-user-agent-capability-standard/df1990d1-4c24-56ea-adb1-a7db50a2bac3/scratchpad/status-draft.md'
const REPO = '/home/user/agent-capability-standard'
const CTX = `The repository is at ${REPO} (git branch claude/gallant-hypatia-wbucn3, HEAD 8e92b2f; origin/main is the base, PR #131 is already merged into main, PR #132 is this branch). The draft status report is at ${DRAFT}. Read it first. It is a status update for the repository's maintainer about everything done in this work and what remains. Read-only task: do NOT edit any file, do not commit, do not push, do not touch GitHub. Useful sources: tasks/todo.md (top sections: "Standard Agent Specification interoperability", "Round 3", "Security review loop", "Round 2"), tasks/standard-1.2/progress/*.md (PHASE4.md, SECURITY-LOOP.md and per-workstream records), tasks/lessons.md, CHANGELOG.md [Unreleased], docs/research/analysis/standard_agents_mapping/*.yaml, docs/reviews/pvc/2026-11-24_standard-1-2-0.pvc.yaml, tasks/standard-agents-upstream/, spec/STANDARD-v1.2.0.md, spec/RFC-000*.md, spec/ROADMAP.md, .claude-plugin/plugin.json, pyproject.toml, CLAUDE.md, git log origin/main..HEAD.`
const CLAIMS = {
  type: 'object',
  properties: {
    checked: { type: 'integer', description: 'number of distinct claims checked' },
    problems: { type: 'array', items: { type: 'object', properties: {
      claim: { type: 'string', description: 'the draft text, quoted' },
      verdict: { type: 'string', enum: ['wrong', 'imprecise', 'unsupported'] },
      evidence: { type: 'string', description: 'file:line and what it says' },
      correction: { type: 'string', description: 'replacement text that is true' },
    }, required: ['claim', 'verdict', 'evidence', 'correction'] } },
  },
  required: ['checked', 'problems'],
}
const SECTIONS = [
  { key: 'mapping', scope: 'section "1. Mapping against the Standard Agent Specification (merged in PR #131)", including every number (319 rows, ten concerns, 83 findings and their 29/54 and 21/11/51 splits, 64 ACS findings, nine issue texts, versions faccc8b and 0.45.10) and the Round 2 bullet (what was fixed, RFC-0005 as Draft at that time).' },
  { key: 'standard', scope: 'section "2. Every ACS finding implemented: Standard 1.2.0 Candidate (PR #132)": the Standard status and compatibility claims, ontology version, RFC statuses, the seven workstreams and their names/scopes, the list of reference layers and the class SL claim, 64 findings fixed, Phase 4 (59 issues) and Phase 5 claims.' },
  { key: 'security', scope: 'sections "3. Security loop" and "4. PVC review": every number (167/147/130, 9/101/20, round 5 with no high, about 20 medium per round), the convergence claim, the PVC counts (15 checks all PARTIAL, 48 evidence entries, 58 actions, 33 P1, 25 P2), and the record locations.' },
  { key: 'ci', scope: 'section "5. Getting PR #132 to green": push protection and the history rewrite, the guard test, the CodeQL fixes (check git log origin/main..HEAD and the diffs of the commits that mention code scanning, CodeQL, regular-expression, comments, built HTML), and the newer-runner fixes (read the last three commits on the branch: git show --stat and the CHANGELOG/SECURITY-LOOP entries they add). Check that each described fix is what the code does.' },
  { key: 'remaining', scope: 'section "What remains": every item. Check each is really still open (not done somewhere in the tree), that the commands, variables and file names are right (file-issues.sh flags and order, NPM_PUBLISH_ENABLED/NPM_TOKEN, version files and current values, the 3.0.0 reasoning in CLAUDE.md), and that each PVC example named in item 6 is really a P1 action in the PVC file.' },
]
const CRITIC = {
  type: 'object',
  properties: { missing: { type: 'array', items: { type: 'object', properties: {
    item: { type: 'string', description: 'an open item, follow-up or caveat the draft omits' },
    evidence: { type: 'string', description: 'file:line where it is recorded as open' },
    importance: { type: 'string', enum: ['high', 'medium', 'low'] },
  }, required: ['item', 'evidence', 'importance'] } } },
  required: ['missing'],
}
const verify = pipeline(SECTIONS, s => agent(
  `${CTX}\n\nYou are a skeptical fact-checker. Your scope: ${s.scope}\nFor every factual claim in that scope, find the primary evidence in the repository and try to refute it. Report only claims that are wrong, imprecise (true in spirit but a number, name or detail is off, or it overstates), or unsupported by anything in the repository. Give a corrected text for each. Do not report style preferences. Do not report claims outside your scope.`,
  { label: `verify:${s.key}`, phase: 'Verify', schema: CLAIMS }))
const critics = parallel([
  () => agent(`${CTX}\n\nYou are a completeness critic. Read tasks/todo.md (the four top sections named above, especially every "Not done", "Not converged" and "Follow-ups" paragraph), every file in tasks/standard-1.2/progress/ (look for open, deferred, not fixed, follow-up, left open, TODO), and tasks/lessons.md. List every open item, deferred follow-up or important caveat recorded there that the draft's "What remains" section does not already cover (even partly covered items count as covered; do not list them). Be exhaustive but do not invent: each item needs a file:line.`, { label: 'critic:records', phase: 'Complete', schema: CRITIC }),
  () => agent(`${CTX}\n\nYou are a completeness critic. Read CHANGELOG.md's [Unreleased] section (especially Upgrading and any known-limitation notes), spec/STANDARD-v1.2.0.md (look for Candidate status, open questions, reserved or future items), each RFC-0005..0010's open questions / unresolved sections, spec/ROADMAP.md, docs/integrations/standard_agents.md (what stays open), tasks/standard-agents-upstream/README.md, the PVC file's actions, and .github/workflows/*.yml for gated jobs (repository variables or secrets that must be set). List every open item or user-facing caveat the draft's "What remains" section does not already cover (partly covered counts as covered). Each item needs a file:line. Do not invent.`, { label: 'critic:docs', phase: 'Complete', schema: CRITIC }),
])
const [v, c] = await Promise.all([verify, critics])
return { verify: v.map((r, i) => ({ section: SECTIONS[i].key, ...(r || { checked: 0, problems: [], failed: true }) })), missing: c.filter(Boolean).flatMap(x => x.missing) }

