"""List implicit string concatenations that are elements of a list literal,
restricted to the given line ranges (file:start-end) or whole files."""
import ast, sys, tokenize, io

def joins(path):
    src = open(path, encoding="utf-8").read()
    tree = ast.parse(src)
    toks = list(tokenize.generate_tokens(io.StringIO(src).readline))
    strings = [t for t in toks if t.type == tokenize.STRING or t.type == getattr(tokenize, "FSTRING_START", -1)]
    out = []
    for node in ast.walk(tree):
        if isinstance(node, ast.List):
            for el in node.elts:
                if isinstance(el, (ast.Constant, ast.JoinedStr)) and isinstance(getattr(el, "value", ""), (str, bytes, list)) or isinstance(el, ast.JoinedStr):
                    n = sum(1 for t in strings if (t.start[0], t.start[1]) >= (el.lineno, el.col_offset) and (t.end[0], t.end[1]) <= (el.end_lineno, el.end_col_offset))
                    if n > 1:
                        out.append(el.lineno)
    return out

for arg in sys.argv[1:]:
    path, _, rng = arg.partition(":")
    lines = joins(path)
    if rng:
        lo, hi = map(int, rng.split("-"))
        lines = [l for l in lines if lo <= l <= hi]
    for l in lines:
        print(f"{path}:{l}")
EOF
