def fake_clock() -> FakeClock:
    """A clock that stands still until the test advances it."""
    return FakeClock()


DEEP_JSON = "[" * 100_000 + "]" * 100_000
"""JSON text nested deeper than Python's json C decoder reads on some
            env={**env, "HOME": str(home)},
            capture_output=True,
            text=True,
            timeout=60,
        )
        assert ("no_such_command" in result.stderr) is reads

    @pytest.mark.parametrize(
        "command",
        [
            "alias g=echo\ng named",
            "hash -p /bin/echo g; g named",
            "BASH_ALIASES[g]=echo\ng named",
            "shopt -s extglob\n./n@(a)med",
            "shopt -s nocaseglob\n./NA?ED",
        ],
    )
    def test_a_name_runs_another_program(self, tmp_path: Path, command: str) -> None:
        script = tmp_path / "named"
        script.write_text("#!/bin/sh\necho named\n")
        script.chmod(0o755)
    @staticmethod
    def _run(driver: Path, *args: str) -> list[str]:
        ours = subprocess.run(
            ["bash", str(driver), *args], capture_output=True, text=True, timeout=30
        )
        assert ours.returncode == 0, (args, ours.stderr)
        return sorted(w for w in ours.stdout.split("\n") if w)

    def test_the_reading_is_bashs(self, tmp_path: Path) -> None:
