    { title: 'Fix', detail: 'apply confirmed findings, rerun the checks' },
  ],
}

const COMMON = `House rules: plain, literal sentences; state the current state, not history; no metaphor. Do not commit, push or switch branches. Do not touch the main checkout at /Users/danielbentes/agent-capability-standard (another task is editing it) except to read; you may use its Python environment: /Users/danielbentes/agent-capability-standard/.venv/bin/python (its editable install of grounded_agency points at the main checkout, which is unchanged for these files). CLAUDE.md in your worktree lists every validator and generator; run the ones your change touches. Node is v26.13.0. If a check cannot run (missing toolchain, network), say so exactly; never claim a check passed that you did not run.`

const ISSUES = [
  { key: '135', wt: '/Users/danielbentes/acs-wt-135', text: `Issue #135 (read it in full: gh api repos/synaptiai/agent-capability-standard/issues/135 --jq .body). The maintainer decided on 2026-11-25:
