]

const FINDINGS = {
  type: 'object',
  properties: {
    findings: {
      type: 'array',
      items: {
        type: 'object',
        properties: {
          severity: { type: 'string', enum: ['P1', 'P2', 'P3'] },
          file: { type: 'string' },
          problem: { type: 'string' },
          fix: { type: 'string' },
        },
        required: ['severity', 'file', 'problem', 'fix'],
      },
    },
  },
  required: ['findings'],
}

const results = await pipeline(
  ISSUES,
  it => agent(`Work in the git worktree ${it.wt} (cd there first; its branch is already checked out).
${it.text}

${COMMON}

Return: files changed with one line each, every command you ran with its result, and anything left unsettled.`, { label: `implement:${it.key}`, phase: 'Implement' }),
  (impl, it) => parallel([
    { lens: 'completeness', text: `Check the change against every checkbox and every "Done when" item of issue #${it.key} (gh api repos/synaptiai/agent-capability-standard/issues/${it.key} --jq .body) and the maintainer's decision above. List each item not done or done wrongly. Also search for places the change missed (git grep for old values).` },
    { lens: 'correctness', text: `Check the change for correctness and regressions: read the diff (git -C ${it.wt} diff; new files via git status --short), run the checks the implementer reports and any it skipped, look for broken references, generated files out of sync, tests that pass for the wrong reason, docs that now contradict code.` },
  ].map(l => () => agent(`Review a change in the git worktree ${it.wt} (uncommitted). Do not edit files.
The task was:
${it.text}

The implementer reported:
${impl}

${l.text}
${COMMON}
Report only real problems, each with the exact fix.`, { label: `review:${it.key}:${l.lens}`, phase: 'Review', schema: FINDINGS }))).then(rs => ({ impl, findings: rs.filter(Boolean).flatMap(r => r.findings) })),
  (r, it) => agent(`Work in the git worktree ${it.wt} (uncommitted change in place).
The task was:
${it.text}

Reviewers found (JSON):
${JSON.stringify(r.findings, null, 2)}

Check each against the files. Fix the real ones (P3 included); for any you reject, give file:line evidence. Then rerun every check listed in the task and report each result.
${COMMON}
Return: per finding fixed/rejected with reason; final changed files; check results.`, { label: `fix:${it.key}`, phase: 'Fix' }).then(fix => ({ key: it.key, impl: r.impl, findings: r.findings, fix })),
)
return results

